// Logo embedded as a build-time base64 constant (rather than read from
// /public at runtime) so it works reliably inside Puppeteer-rendered PDFs
// on serverless (Vercel's function bundler doesn't always trace dynamic
// fs.readFileSync calls to include /public assets).
export function getLogoDataUri(): string {
  return LOGO_BASE64;
}

const LOGO_BASE64 = "data:image/png;base64,";
